const responseData = pm.response.json();

// 1. Status code should be 200
pm.test("Status code is 200", function () {
    pm.response.to.have.status(200);
});

// 2. Response should be a non-empty array
pm.test("Response is a non-empty array", function () {
    pm.expect(responseData).to.be.an("array").that.is.not.empty;
});

// 3. Each user should have id, name, and email
pm.test("Each user contains id, name, and email", function () {
    responseData.forEach((user) => {
        pm.expect(user).to.have.property("id");
        pm.expect(user).to.have.property("name").that.is.a("string").and.not.empty;
        pm.expect(user).to.have.property("email").that.is.a("string").and.not.empty;
    });
});

// 4. Select any one user's ID and save it in a local variable
const selectedUser = responseData[0]; // or random index
pm.collectionVariables.set("id", selectedUser.id);

const responseData = pm.response.json();
const expectedId = Number(pm.variables.get("id"));
const expectedName = pm.variables.get("updatedName");

// 1. Status code should be 200 (mandatory on every request)
pm.test("Status code is 200", function () {
    pm.response.to.have.status(200);
});

// 2. Returned ID should match the ID stored in the variable
pm.test("Returned ID matches stored ID", function () {
    pm.expect(responseData.id).to.eql(expectedId);
});

// 3. Phone should not be empty
pm.test("Phone should not be empty", function () {
    pm.expect(responseData.phone).to.be.a("string").and.not.be.empty;
});

// 4. Returned name should match the updated name
pm.test("Returned name matches updated name", function () {
    pm.expect(responseData.name).to.eql(expectedName);
});
